@media(max-width:600px){.home .metrics{padding:22px 8px}.home .metric-icon svg{width:26px;height:26px}.home .metrics strong{font-size:36px}.home .metrics div>span:last-child{font-size:11px}.home .statement{min-height:530px;padding:45px 20px}.home .statement>div{padding:55px 22px;min-height:400px}.home .field{height:620px}.home .field h2{bottom:7%}.home .news{padding:45px 20px}.news-heading h2{font-size:28px}.news-controls button{width:35px;height:35px}.home .news article>div{padding:22px}.home .contribute{padding:45px 24px;gap:24px}.home .contribute h2{font-size:27px}:is(.home,.contact-page) .footer{padding:38px 24px 25px}:is(.home,.contact-page) .subscribe{grid-template-columns:minmax(0,1fr) auto;width:100%}:is(.home,.contact-page) .subscribe button{padding:12px 16px}.email-shell{padding:0 10px}:is(.home,.contact-page) .subscribe input{font-size:12px;padding:12px 6px}:is(.home,.contact-page) .footer-bottom{align-items:flex-start;flex-direction:column;gap:22px}.footer-links{gap:18px}}

/* Refined glass width, compact KPI typography, original footer branding. */
.home .statement>div{width:82%;height:400px;min-height:400px;padding:60px 4%}.home .statement h2{font-size:clamp(18px,2.65vw,40px);white-space:nowrap;letter-spacing:-.035em}.home .statement p{font-size:clamp(14px,1.2vw,18px)}
.home .impact-heading{padding:24px 20px 8px}.home .impact-heading .eyebrow{font-size:14px}.home .impact h2{font-size:clamp(26px,2.2vw,36px);margin-top:8px}.home .metrics{padding:24px 20px 28px}.home .metric-icon{margin-bottom:12px}.home .metric-icon svg{width:26px;height:26px}.home .metrics strong{font-size:clamp(28px,2.65vw,42px)}.home .metrics div>span:last-child{font-size:clamp(12px,1.05vw,17px);margin-top:8px}
:is(.home,.contact-page) .footer-wordmark img{width:214px;min-width:0;height:auto;display:block;filter:none;mix-blend-mode:normal}
@media(max-width:600px){.home .statement>div{width:100%;height:400px;padding:45px 12px}.home .statement h2{font-size:clamp(12px,3.45vw,21px)}.home .metrics{padding:20px 8px 24px}.home .metrics strong{font-size:28px}.home .metrics div>span:last-child{font-size:11px}.home .impact-heading .eyebrow{font-size:12px}:is(.home,.contact-page) .footer-wordmark img{width:180px}}

/* A little more breathing room for the contribution section. */
.home .contribute{padding:74px max(24px,calc((100% - 1120px)/2));gap:90px}.home .contribute>div{max-width:760px}@media(max-width:800px){.home .contribute{gap:32px;padding:54px 24px}}

@media(prefers-reduced-motion:no-preference){.reveal-pending{opacity:0;transform:translateY(18px);transition:opacity .65s ease,transform .65s cubic-bezier(.2,.65,.3,1)}.reveal-pending.reveal-visible{opacity:1;transform:translateY(0)}}

/* Keep the KPI overlap above the hero even when reveal creates stacking contexts. */
.home .impact-section{position:relative;z-index:3;display:flow-root;overflow:visible}.home .impact{margin-top:-6.7vw}@media(max-width:600px){.home .impact{margin-top:-52px}}
